import {course,sources} from './course.js';
import {createLab,act,validate} from './engine.js';
import {renderLab} from './labs.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='plc-workshop-progress-v1';
let storageOK=true,state={module:0,tab:'learn',progress:course.map(()=>({lab:false,quiz:{}}))};
try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&Array.isArray(x.progress)&&x.progress.length===12){state.module=Number.isInteger(x.module)&&x.module>=0&&x.module<12?x.module:0;state.tab=['learn','practice','check'].includes(x.tab)?x.tab:'learn';state.progress=x.progress.map(p=>({lab:p?.lab===true,quiz:Object.fromEntries(Object.entries(p?.quiz||{}).filter(([k,v])=>['0','1','2'].includes(k)&&v?.correct===true))}));}}catch{storageOK=false;}
const labs=course.map((_,i)=>createLab(i));
let selected=null,feedback=null,hintLevel=0,attempts=0,labFeedback=null,menu=false,modal=null,questionCursor=0;
const icon=`<svg viewBox="0 0 36 36" fill="none" aria-hidden="true"><path d="M4 18h8m12 0h8M12 8v20M24 8v20" stroke="currentColor" stroke-width="3"/><path d="M15 5h6m-6 26h6" stroke="currentColor" stroke-width="2"/></svg>`;
const current=()=>course[state.module],progress=()=>state.progress[state.module];
const complete=i=>state.progress[i].lab&&Object.keys(state.progress[i].quiz).length===3;
const percent=()=>Math.round(state.progress.reduce((n,p)=>n+(p.lab?1:0)+Object.keys(p.quiz).length,0)/48*100);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function firstQuestion(){questionCursor=[0,1,2].find(i=>!progress().quiz[i])??3;selected=null;feedback=null;hintLevel=0;attempts=0;}
firstQuestion();
function nav(){return `<aside class="sidebar ${menu?'is-open':''}" aria-label="Course navigation"><a class="brand" href="#" data-do="home"><span class="brand-mark">${icon}</span><span>PLC <b>Workshop</b><small>YOUR TECHNICIAN COURSE</small></span></a><div class="course-summary"><span class="tiny">YOUR PROGRESS</span><strong>${percent()}<small>%</small></strong><div class="progress-track"><i style="width:${percent()}%"></i></div><p>${state.progress.filter((_,i)=>complete(i)).length} of 12 modules completed</p></div><div class="nav-label">THE LEARNING PATH</div><nav>${course.map((m,i)=>`<button data-module="${i}" class="module-link ${i===state.module?'selected':''}" ${i===state.module?'aria-current="step"':''}><span class="module-number ${complete(i)?'done':''}">${complete(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${m.short}</span>${i===state.module?'<i>›</i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="small-dot"></span>Everything you need is here<p>No installations. No answer key.</p><button class="text-button" data-do="about">About this course ↗</button></div></aside>`;}
function shell(){const m=current();$('#app').innerHTML=`${nav()}<div class="workspace"><header class="topbar"><button class="menu-button" data-do="menu" aria-label="Toggle course navigation" aria-expanded="${menu}">☰</button><span>YOUR WORKSHOP <i>/</i> <b>Module ${String(state.module+1).padStart(2,'0')}</b></span><span class="save-state"><span class="small-dot"></span>${storageOK?'Progress saved in this browser':'Progress available this session'}</span></header><main id="main" tabindex="-1"><div class="lesson-heading"><div><div class="eyebrow">${m.eyebrow} <span>MODULE ${state.module+1} OF 12</span></div><h1>${m.title}</h1><p>${m.goal}</p></div><div class="time-badge"><span>AT YOUR PACE</span><b>${m.time}</b><small>Suggested first pass</small></div></div><div class="tabs" role="tablist" aria-label="Lesson sections">${[['learn','01','Learn'],['practice','02','Practice'],['check','03','Check understanding']].map(([id,n,label])=>`<button id="tab-${id}" role="tab" aria-selected="${state.tab===id}" aria-controls="panel" data-tab="${id}" class="${state.tab===id?'active':''}"><small>${n}</small>${label}${id==='practice'&&progress().lab?'<span class="tab-check">✓</span>':''}${id==='check'&&Object.keys(progress().quiz).length===3?'<span class="tab-check">✓</span>':''}</button>`).join('')}</div><section id="panel" role="tabpanel" aria-labelledby="tab-${state.tab}">${state.tab==='learn'?learn():state.tab==='practice'?practice():check()}</section><footer class="course-footer"><span>PLC Workshop · Guided foundations</span><button data-do="about">Course notes & sources</button></footer></main></div>${modal?dialog():''}`;}
function learn(){const m=current();return `<div class="learn-grid"><article class="lesson-paper"><div class="section-kicker">A SMALL LESSON. A REAL SKILL.</div>${m.lesson.map(([title,body],i)=>`<section class="reading-section"><span class="reading-number">${i+1}</span><div><h2>${title}</h2><p>${body}</p></div></section>`).join('')}<div class="reading-bottom"><span>Take your time. Understanding comes before speed.</span><button class="primary" data-tab="practice">Open the practice bench <span>→</span></button></div></article><aside class="lesson-aside"><div class="bench-preview"><div class="preview-meta"><span class="live-dot"></span>BUILT INTO YOUR COURSE</div><div class="mini-plc"><div class="mini-brand">PLC <b>01</b></div><div class="terminal-row">${Array.from({length:7},()=>'<i></i>').join('')}</div><div class="plc-display"><span>READY TO LEARN</span><strong>INPUT <i>→</i> LOGIC <i>→</i> OUTPUT</strong></div><div class="terminal-row">${Array.from({length:7},()=>'<i></i>').join('')}</div><span class="mini-light"></span></div><h3>Your bench is ready.</h3><p>${m.lab}</p><button class="light-button" data-tab="practice">Try it yourself ↗</button></div><div class="vocabulary"><div class="section-kicker">WORDS YOU WILL USE</div><div>${m.terms.map(t=>`<span>${t}</span>`).join('')}</div></div><div class="coach-note"><div class="coach-symbol">?</div><div><h3>Hints, not handouts.</h3><p>Try a question. Get feedback. If you’re stuck, a hint helps you decide what to look at next.</p></div></div></aside></div>`;}
function practice(){return `<div class="practice-grid"><div><section class="bench" id="bench" aria-label="Interactive PLC training bench">${renderLab(labs[state.module])}</section><div id="lab-feedback">${labFeedbackHTML()}</div></div><aside class="practice-guide"><div class="section-kicker">YOUR PRACTICE TASK</div><h2>Make it work.<br>Then prove it.</h2><p>${current().lab}</p><div class="practice-tips"><h3>Use a technician’s routine</h3><ol><li>Predict the result.</li><li>Change one condition.</li><li>Observe what happened.</li><li>Explain any mismatch.</li></ol></div><button class="primary full" data-do="validate">${state.module===11?'Run acceptance checks':'Check practice'} <span>→</span></button><button class="secondary full" data-do="resetLab">Reset this bench</button><p class="subtle">${progress().lab?'✓ This practice is completed. You can keep experimenting.':'Completing this practice and all three questions completes the module.'}</p><button class="text-button" data-tab="check">Go to the questions →</button></aside></div>`;}
function labFeedbackHTML(){return labFeedback?`<div class="feedback ${labFeedback.ok?'success':'guidance'}" role="status"><b>${labFeedback.ok?'Practice complete':state.module===10&&labs[10].diagnosed>labs[10].faultCase?'Diagnosis supported':'Keep investigating'}</b><p>${esc(labFeedback.text)}</p>${labFeedback.ok?'<button class="text-button" data-tab="check">Check your understanding →</button>':''}</div>`:'';}
function check(){
 if(questionCursor>=3)return `<div class="checkpoint-complete"><span class="completion-icon">✓</span><div class="section-kicker">KNOWLEDGE CHECK COMPLETE</div><h2>${progress().lab?'You’ve completed this module.':'You understand the concept.'}</h2><p>${progress().lab?'Your practice and three questions are complete. Bring these ideas into the next module.':'Complete the practice task to put your understanding to work and finish the module.'}</p><div class="completion-stats"><div><b>3 / 3</b><span>Questions completed</span></div><div><b>${Object.values(progress().quiz).filter(v=>!v.assisted).length}</b><span>Answered without hints or retries</span></div></div>${progress().lab?(state.module<11?'<button class="primary" data-do="nextModule">Continue to the next module →</button>':`<div class="course-achievement"><h3>${state.progress.every((_,i)=>complete(i))?'Your foundation course is complete.':'Final module complete.'}</h3><p>${state.progress.every((_,i)=>complete(i))?'You have completed 12 practice tasks and 36 guided questions. Real equipment practice still requires site training and supervision.':'Use the learning path to finish any remaining modules.'}</p></div>`):'<button class="primary" data-tab="practice">Complete the practice →</button>'}<button class="secondary" data-do="reviewQuestions">Practice these questions again</button></div>`;
 const q=current().questions[questionCursor];return `<div class="check-grid"><article class="question-card"><div class="question-top"><span class="section-kicker">CHECK YOUR UNDERSTANDING</span><span>Question ${questionCursor+1} / 3</span></div><div class="question-dots">${[0,1,2].map(i=>`<i class="${i<questionCursor?'passed':i===questionCursor?'current':''}"></i>`).join('')}</div><h2 id="question-title" tabindex="-1">${q.prompt}</h2><div class="answers" role="radiogroup" aria-labelledby="question-title">${q.options.map((a,i)=>`<button class="answer ${selected===i?'selected':''}" role="radio" aria-checked="${selected===i}" data-option="${i}" ${feedback?.correct?'disabled':''}><span>${'ABCD'[i]}</span><b>${a}</b><i>${selected===i?'●':'○'}</i></button>`).join('')}</div>${feedback?`<div class="feedback ${feedback.correct?'success':'guidance'}" role="status"><b>${feedback.correct?'Correct. You’ve got it.':'Not quite. Let’s work through it.'}</b><p>${feedback.text}</p></div>`:''}<div class="question-actions">${feedback?.correct?'<button class="primary" data-do="nextQuestion">Continue →</button>':`<button class="primary" data-do="submit" ${selected===null?'disabled':''}>Check my answer →</button><button class="secondary" data-do="hint">${hintLevel?'Another hint':'Give me a hint'}</button>`}</div>${hintLevel?`<div class="hint" role="status"><span>HINT ${Math.min(hintLevel,q.hints.length)}</span><p>${q.hints[Math.min(hintLevel,q.hints.length)-1]}</p>${hintLevel>q.hints.length?'<p>Take a step back: describe what you know, then compare each remaining choice against the lesson. You can revisit the explanation and return to this question.</p><button class="text-button" data-tab="learn">Revisit the concept →</button>':''}</div>`:''}</article><aside class="question-aside"><div class="coach-portrait">${icon}</div><div class="section-kicker">ONE QUESTION AT A TIME</div><h3>You do the thinking.<br>We guide the next step.</h3><p>A wrong attempt is useful information. You’ll get a cue to revisit the concept, then another try. The course never shows an answer key or a “reveal answer” button.</p><div class="question-support"><b>Need to see it happen?</b><button class="text-button" data-tab="practice">Return to the practice bench ↗</button></div></aside></div>`;
}
function dialog(){return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-do="close" aria-label="Close course notes">×</button><div class="section-kicker">ABOUT THE COURSE</div><h2 id="modal-title">All your practice, in one place.</h2><p>This foundation course includes 12 short lessons, 12 interactive practice tasks, and 36 questions with guided hints. Each module can be revisited as often as needed. Suggested times cover a first pass; repeat labs to strengthen understanding.</p><p>These are simplified educational models. They do not connect to equipment, certify job readiness, or replace manufacturer instructions and supervised training. All required learning and exercises are inside the course.</p><h3>Your progress</h3><p>Progress is saved on this browser and device. Clearing browser data can remove it. There is no cross-device sync. The feedback is based on the course’s predefined checks and hints, not an open-ended AI chat.</p><h3>Optional technical references</h3><p>You do not need these links to take the course. They support the concepts and explain how real instruction behavior can vary.</p><ul>${sources.map(([t,u])=>`<li><a target="_blank" rel="noopener" href="${u}">${t} ↗</a></li>`).join('')}</ul><p class="subtle">References checked October 12, 2026.</p><button class="primary" data-do="close">Back to my course</button></section></div>`;}
function renderBench(){const active=document.activeElement?.dataset;const focusSelector=active?.field?`[data-field="${active.field}"]`:active?.act?`[data-act="${active.act}"]`:null;const el=$('#bench');if(el)el.innerHTML=renderLab(labs[state.module]);const fb=$('#lab-feedback');if(fb)fb.innerHTML=labFeedbackHTML();if(focusSelector)$(focusSelector)?.focus({preventScroll:true});}
function setTab(tab){state.tab=tab;menu=false;save();shell();$(`#tab-${tab}`)?.focus({preventScroll:true});}
function switchModule(i){state.module=i;state.tab='learn';labFeedback=null;menu=false;firstQuestion();save();shell();window.scrollTo({top:0,behavior:'smooth'});}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,a');if(!el)return;
 if(el.dataset.module!==undefined){switchModule(Number(el.dataset.module));return;}
 if(el.dataset.tab){setTab(el.dataset.tab);return;}
 if(el.dataset.option!==undefined){selected=Number(el.dataset.option);feedback=null;shell();$(`[data-option="${selected}"]`)?.focus({preventScroll:true});return;}
 if(el.dataset.act){act(labs[state.module],el.dataset.act,el.dataset.value);labFeedback=null;renderBench();return;}
 const action=el.dataset.do;if(!action)return;
 if(action==='menu'){menu=!menu;shell();}
 if(action==='home'){e.preventDefault();switchModule(0);}
 if(action==='about'){modal='about';shell();$('.modal-close')?.focus();}
 if(action==='close'){modal=null;shell();}
 if(action==='validate'){
  const v=validate(labs[state.module]);labFeedback={...v,text:v.ok?'You tested the required behavior successfully. Explain to yourself why it worked before moving on.':v.text};if(v.ok){progress().lab=true;save();shell();}else renderBench();
 }
 if(action==='resetLab'){labs[state.module]=createLab(state.module);labFeedback=null;renderBench();}
 if(action==='hint'){hintLevel++;shell();}
 if(action==='submit'&&selected!==null){
  const q=current().questions[questionCursor];const right=selected===q.answer;
  if(right){progress().quiz[questionCursor]={correct:true,assisted:attempts>0||hintLevel>0};feedback={correct:true,text:q.why};save();}
  else{attempts++;feedback={correct:false,text:q.feedback?.[selected]||q.hints[Math.min(attempts-1,q.hints.length-1)]};}
  shell();
 }
 if(action==='nextQuestion'){questionCursor++;selected=null;feedback=null;hintLevel=0;attempts=0;shell();$('#question-title')?.focus();}
 if(action==='reviewQuestions'){questionCursor=0;selected=null;feedback=null;hintLevel=0;attempts=0;shell();}
 if(action==='nextModule')switchModule(Math.min(11,state.module+1));
});
document.addEventListener('change',e=>{if(e.target.dataset.field){const key=e.target.dataset.field;act(labs[state.module],key,e.target.value);labFeedback=null;renderBench();}});
document.addEventListener('keydown',e=>{
 if(e.target.dataset?.option!==undefined&&['ArrowDown','ArrowRight','ArrowUp','ArrowLeft'].includes(e.key)&&!feedback?.correct){e.preventDefault();const d=['ArrowDown','ArrowRight'].includes(e.key)?1:-1;selected=(Number(e.target.dataset.option)+d+4)%4;feedback=null;shell();$(`[data-option="${selected}"]`)?.focus();}
 if(e.key==='Escape'&&modal){modal=null;shell();}
 if(modal&&e.key==='Tab'){const items=[...document.querySelectorAll('.modal button,.modal a')],first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
shell();
